const ALL = ['2026Instock','Animal','Balustrade','Bathtub','Bench','BookMatchedSlabs','Carving','Columns','DoorSurround','Exterior-Wall-Decoration','Fireplace','Fountain','Lamppost','Marble+ Basin','Marble+ ConsoleTable','MarbleMedallion','MarbleRangeHood','MarbleSlab','Moulding','OutdoorCornice','Planter','Sink','Stairs','Statue','StoneMosaicTile','Table','Vanity','Wainscoting','Wall-Coverings','WindowSurround'];
const wanted = String($('Config').first().json.sheets || '').split(',').map(s => s.trim()).filter(Boolean);
return ALL.filter(s => !wanted.length || wanted.includes(s)).map(sheet_name => ({ json: { sheet_name } }));

// Finds the columns this check needs: Product No., IMAGE URL11 (the CAD drawing in the gallery), CAD Drawing URL (the download button) and the size columns.
const DOC = '1ITSJNL7iql08AklUOLI1QSpOO0HlYEb8Dui0eNBXSeI';
const SHEET = $('Loop Through Sheets').first().json.sheet_name;
const headers = ($input.first().json.values?.[0] || []).map(h => String(h ?? '').trim());
const find = (re) => headers.findIndex(h => re.test(h));
const spec = [
  { name: 'sku', idx: headers.lastIndexOf('Product No.') },
  { name: 'cad', idx: headers.lastIndexOf('IMAGE URL11') },
  { name: 'btn', idx: headers.lastIndexOf('CAD Drawing URL') },
  { name: 'L', idx: find(/^length\b/i) },
  { name: 'W', idx: find(/^width\b/i) },
  { name: 'H', idx: find(/^height\b/i) },
  { name: 'D', idx: find(/^diameter\b/i) },
];
const missing = spec.filter(c => c.idx < 0).map(c => c.name);
const letters = (n) => { let s = ''; n += 1; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; };
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;
const cols = spec.filter(c => c.idx >= 0);
const ranges = cols.length ? cols.map(c => `${q(SHEET)}!${letters(c.idx)}3:${letters(c.idx)}`) : [`${q(SHEET)}!A2:A2`];
const url = `https://sheets.googleapis.com/v4/spreadsheets/${DOC}/values:batchGet?majorDimension=COLUMNS&valueRenderOption=FORMATTED_VALUE&` + ranges.map(r => 'ranges=' + encodeURIComponent(r)).join('&');
return [{ json: { sheet_name: SHEET, cols, missing, url } }];

// Turns the columns of one tab into one record per product (no judgement yet; the Final Report compares across all tabs).
const plan = $('Plan Columns').first().json;
const vr = $input.first().json.valueRanges || [];
const col = {}; plan.cols.forEach((c, i) => { col[c.name] = vr[i]?.values?.[0] || []; });
const base = (u) => String(u || '').split('?')[0].trim();
const fileOf = (u) => { const l = base(u).split('/').pop() || ''; try { return decodeURIComponent(l); } catch (e) { return l; } };
const keyOf = (name) => name.toLowerCase().replace(/\.[a-z0-9]+$/, '')
  .replace(/_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/, '')
  .replace(/_0000\d$/, '').replace(/\s*\(\d+\)$/, '');
const num = (v) => { const n = parseFloat(String(v ?? '').replace(',', '.')); return isFinite(n) && n > 0 ? n : null; };
const nRows = Math.max(0, ...Object.values(col).map(a => a.length));
const recs = [];
let rows = 0;
for (let i = 0; i < nRows; i++) {
  const sku = String((col.sku || [])[i] ?? '').trim();
  if (!sku) continue;
  rows++;
  const cadUrl = String((col.cad || [])[i] ?? '').trim();
  const btnUrl = String((col.btn || [])[i] ?? '').trim();
  const hasCad = /^https?:/i.test(cadUrl);
  const hasBtn = /^https?:/i.test(btnUrl);
  const dims = ['L', 'W', 'H', 'D'].map(k => num((col[k] || [])[i])).filter(Boolean).sort((a, b) => b - a);
  recs.push({
    row: i + 3, sku,
    cadFile: hasCad ? fileOf(cadUrl) : '', cadKey: hasCad ? keyOf(fileOf(cadUrl)) : '',
    btnFile: hasBtn ? fileOf(btnUrl) : '', btnKey: hasBtn ? keyOf(fileOf(btnUrl)) : '',
    dims,
  });
}
return [{ json: { tab: plan.sheet_name, rows, missingColumns: plan.missing, recs } }];

