const tabs = $input.all().map(i => i.json);
const recs = tabs.flatMap(t => (t.recs || []).map(r => ({ ...r, tab: t.tab })));

const split = (s) => { const m = String(s).match(/^([A-Za-z]+)(\d+)$/); return m ? { L: m[1].toUpperCase(), N: parseInt(m[2], 10) } : null; };
const prefixes = new Set(recs.map(r => split(r.sku)).filter(Boolean).map(p => p.L));
const knownLetters = (L) => prefixes.has(L) || (L.length >= 2 && [...prefixes].some(p => p.endsWith(L)));
const compatible = (a, b) => a === b || a.endsWith(b) || b.endsWith(a);

const flags = new Map();
const flag = (r, reason, detail) => {
  const k = r.tab + '|' + r.row;
  if (!flags.has(k)) flags.set(k, { rec: r, reasons: [] });
  flags.get(k).reasons.push({ reason, detail });
};

// 1) the CAD file name carries a different product number than the row
for (const r of recs) {
  if (!r.cadFile) continue;
  const own = split(r.sku);
  const re = /([A-Za-z]{2,6})(\d{2,4})(?!\d)/g; let m;
  while ((m = re.exec(r.cadFile)) !== null) {
    const L = m[1].toUpperCase(); const N = parseInt(m[2], 10);
    if (!knownLetters(L)) continue;
    if (own && own.N === N && compatible(own.L, L)) continue;
    flag(r, 'file_name_other_product', 'file name has ' + m[1] + m[2] + ' but the row is ' + r.sku);
    break;
  }
}

// 2) group by drawing; same drawing on different tabs, or on products of clearly different size (only when length, width and height are all known)
const groups = new Map();
for (const r of recs) { if (!r.cadKey) continue; if (!groups.has(r.cadKey)) groups.set(r.cadKey, []); groups.get(r.cadKey).push(r); }
const median = (a) => { const s = [...a].sort((x, y) => x - y); const h = Math.floor(s.length / 2); return s.length % 2 ? s[h] : (s[h - 1] + s[h]) / 2; };
const fmt = (d) => d.length ? d.map(x => Math.round(x * 10) / 10).join('x') : 'no size';
const typicalByKey = new Map();
for (const [key, members] of groups) {
  const tabSet = [...new Set(members.map(m => m.tab))];
  if (tabSet.length > 1) members.forEach(m => flag(m, 'same_drawing_on_other_category', 'drawing ' + members[0].cadFile + ' is also used in ' + tabSet.filter(t => t !== m.tab).join(', ')));
  let typical = null;
  if (members.length >= 2) {
    const full = members.filter(m => m.dims.length >= 3);
    if (full.length >= 2) {
      typical = [0, 1, 2].map(i => median(full.map(m => m.dims[i])));
      for (const m of full) {
        const off = [0, 1, 2].some(i => Math.abs(m.dims[i] - typical[i]) > Math.max(1.5, 0.05 * typical[i]));
        if (off) flag(m, 'size_differs_from_group', 'size ' + fmt(m.dims) + ' vs typical ' + fmt(typical) + ' for ' + m.cadFile);
      }
    }
  }
  typicalByKey.set(key, typical ? fmt(typical) : 'not compared');
}

// 3) the download button points to a different drawing than the gallery
const perTab = tabs.map(t => {
  const rs = (t.recs || []);
  const withCad = rs.filter(r => r.cadFile);
  let be = 0, bd = 0;
  for (const r of withCad) {
    const full = recs.find(x => x.tab === t.tab && x.row === r.row);
    if (!r.btnFile) be++;
    else if (r.btnKey !== r.cadKey) { bd++; flag(full, 'download_button_differs', 'button ' + r.btnFile + ' vs gallery ' + r.cadFile); }
  }
  const gapRecs = withCad.filter(r => GAP.has(r.sku));
  return { tab: t.tab, products: t.rows, withCad: withCad.length, inGapList: gapRecs.length, drawingsInGapList: new Set(gapRecs.map(r => r.cadKey)).size, downloadButtonEmpty: be, downloadButtonDiffers: bd, sizeColumnsNotFound: t.missingColumns };
});

const suspicious = [...flags.values()].map(f => ({
  tab: f.rec.tab, row: f.rec.row, sku: f.rec.sku, inGapList: GAP.has(f.rec.sku), cad: f.rec.cadFile,
  reasons: f.reasons.map(x => x.reason).join(' + '), detail: f.reasons.map(x => x.detail).join(' | '),
})).sort((a, b) => (b.inGapList - a.inGapList) || a.tab.localeCompare(b.tab) || a.row - b.row);
const byReason = {};
flags.forEach(f => f.reasons.forEach(x => { byReason[x.reason] = (byReason[x.reason] || 0) + 1; }));

// What a person needs to look at: each drawing used by the gap products, once.
const sharedDrawings = []; const singleUse = [];
for (const [key, members] of groups) {
  const gm = members.filter(m => GAP.has(m.sku));
  if (!gm.length) continue;
  if (members.length === 1) singleUse.push(gm[0].tab + ' | ' + gm[0].sku + ' | ' + gm[0].cadFile);
  else sharedDrawings.push({ n: gm.length, line: gm[0].tab + ' | ' + members[0].cadFile + ' | ' + gm.length + ' of ' + members.length + ' products | size ' + typicalByKey.get(key) + ' | e.g. ' + gm.slice(0, 3).map(m => m.sku).join(', ') });
}
sharedDrawings.sort((a, b) => b.n - a.n);

return [{ json: {
  readOnly: true,
  products: recs.length,
  withCad: recs.filter(r => r.cadFile).length,
  distinctDrawings: groups.size,
  suspiciousProducts: suspicious.length,
  suspiciousInGapList: suspicious.filter(s => s.inGapList).length,
  byReason,
  perTab,
  suspicious: suspicious.slice(0, 80),
  moreSuspiciousNotShown: Math.max(0, suspicious.length - 80),
  drawingsUsedByGapProducts: sharedDrawings.length + singleUse.length,
  sharedDrawingsToReview: sharedDrawings.map(x => x.line),
  singleUseDrawingsToReview: singleUse,
} }];
